import { levelFromXp, totalXp } from "./rules.js";

export function renderPlayer(state){
    const stats = levelFromXp(totalXp(state));
    document.getElementById("name").textContent = state.name;
    document.getElementById("level").textContent = stats.level;
    document.getElementById("xp").textContent = stats.xp + '/' + stats.need;
}import {load } from "../js/storage.js"
import { renderPlayer } from "./render.js";
import { percentDone, totalXp, levelFromXp} from "./rules.js";

const state = load();

const stats = levelFromXp(totalXp(state));

document.getElementById("remplissage").style.width = percentDone(stats.xp, stats.need);

console.log(stats.xp);
console.log(stats.need);

renderPlayer(state);#piste{
    height: 30px;
    width: 300px;
    background-color: gray;
    border-radius: 20px;
    overflow: hidden;
}

#remplissage{
    height: 100%;
    background-color: green;
}export function kgToGo(current, target)
{
    let count = target - current;
    if (current >= target)
        count = 0;
    if (count > target)
        count = "Error";
    return (count);
}

export function percentDone(current, target)
{
    return (current / target) * 100;
}

export function formatLevel(lvl, current, target)
{
    let count = kgToGo(current, target);
    return (`Level ${lvl} : ${count}/${target}`);
}

export function parseSteps(text){
    return text
    .split("\n")
    .map(str => str.trim())
    .filter(str => str !== "")
    .map(str => ({text: str, done: false}));
}

export function projectProgress(project){
    const steps_progress = project.steps.filter(step => step.done);
    return { done: steps_progress.length, total: project.steps.length };
}

export function isProjectComplete(project){
    return projectProgress(project).done === projectProgress(project).total;
}

const STEP_XP = 50;

export function totalXp(state){
    const initialValue = 0;
    return state.projects.reduce((accumulator, currentValue) =>
        accumulator + (projectProgress(currentValue).done * STEP_XP), initialValue);
}

function xpToNextLevel(level){
    return (level * 100);
}

export function levelFromXp(total){
    let level = 1;
    while(total >= xpToNextLevel(level)){
        total -= xpToNextLevel(level);
        level++;
    }
    return {level, xp: total, need: xpToNextLevel(level)};
}

